    hebrewTranslation: `הסדר הארבעה־עשר:
שיבוץ “הדרך נופלת”

סדר זה נקרא “אייקע אל־טאריק” — כלומר סדר שבו הדרך נופלת במהלכה. נקודת האש בו תשע, האוויר מאתיים, המים עשר, והעפר מאה.

אג׳ליד, אחר כך חיבור, ממון יוצא ושפל ראש — נלחם עם ראיית אל־אפרח;

בר הלחי, אדום, נשוא ראש ולבן יחד — ראיית אל־חזן וממון נכנס;

ת׳קאף ותשמיר, אבריד וקהלה — זהו ציור הדרך הברור.

שיבוץ הדרך הנופלת — סדר הצורות

והנה הסדר הזה מיוסד על מה שנתבאר בדרך יזדג׳.

הסדר החמישה־עשר: שיבוץ בן־מחפוף אל־מונַג׳ם

גם סדר זה נמסר בשיר, והוא חותם את סדרי השיבוץ החשבוניים:

בן־מחפוף הוא המנַג׳ם, והוא שיבוץ צורות שבו ייחתם הסדר;

הדרך היא הראשונה הנגלית, וראיית אל־אפרח צורה שנייה;

אחר כך בר הלחי ונלחם, וראיית אל־חזן אתה מתקן;

תשמיר, סוהר ואג׳ליד; וחיבור דינו קשור;

ממון נכנס ואחריו ממון יוצא, שפל ראש ונשוא ראש ומטרוש השגוי;

ואחר כך הלבן ואל־מסדוד — ובו נחתמת ההכאה.

שיבוץ בן־מחפוף — סדר הצורות`,
